versions.variantCss:
.wemd-table[data-variant="bytedance-table-simple"] {
  margin: 16px 0;
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  overflow: hidden;
  border: 1px solid var(--wemd-border-soft);
}
.wemd-table[data-variant="bytedance-table-simple"] .wemd-component-body {
  padding: 0;
}
.wemd-table[data-variant="bytedance-table-simple"] .wemd-component-body .wemd-child-1 {
  background: var(--wemd-bg-muted);
  color: var(--wemd-text-strong);
  font-size: 14px;
  font-weight: 700;
  padding: 10px 16px;
  margin: 0;
  border-bottom: 2px solid var(--wemd-primary);
}
.wemd-table[data-variant="bytedance-table-simple"] .wemd-component-body .wemd-child-2,
.wemd-table[data-variant="bytedance-table-simple"] .wemd-component-body .wemd-child-3 {
  color: var(--wemd-text-normal);
  font-size: 14px;
  padding: 10px 16px;
  margin: 0;
  border-bottom: 1px solid var(--wemd-border-soft);
}
